//! Terminal UI utilities.
//!
//! Centralises how text is rendered to a terminal so the colour scheme can
//! be adjusted in one place (and later driven by a `/colour` REPL command).
//!
//! The default foreground colour is dark blue. Colour codes are only emitted
//! when stdout is a terminal; when piped or redirected the text is plain, so
//! logs and captured output stay clean.

use std::fmt;
use std::io::{self, IsTerminal};

/// A foreground colour for terminal text.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Colour {
    DarkBlue,
    Reset,
    /// Plain output — no colour code emitted.
    Plain,
}

impl Colour {
    /// The ANSI SGR foreground escape sequence for this colour, or empty
    /// when the output is not a terminal.
    fn sgr(self, emit: bool) -> &'static str {
        if !emit {
            return "";
        }
        match self {
            Colour::DarkBlue => "\x1b[34m",
            Colour::Reset => "\x1b[0m",
            Colour::Plain => "",
        }
    }
}

/// The active colour scheme. Defaults to dark blue; a future `/colour`
/// command will mutate the current scheme.
#[derive(Debug, Clone, Copy)]
pub struct Theme {
    /// Whether ANSI codes should be emitted (true when stdout is a TTY).
    emit: bool,
    /// The default foreground colour.
    default: Colour,
}

impl Default for Theme {
    fn default() -> Self {
        Self {
            emit: io::stdout().is_terminal(),
            default: Colour::DarkBlue,
        }
    }
}

impl Theme {
    /// Create a theme for the current terminal.
    pub fn new() -> Self {
        Self::default()
    }

    /// Wrap `s` in colour escapes: `default` colour, then reset.
    fn paint(&self, s: &str) -> String {
        let fg = self.default.sgr(self.emit);
        let reset = Colour::Reset.sgr(self.emit);
        format!("{fg}{s}{reset}")
    }

    /// A `write!`-style target that applies the default colour to every
    /// formatted value. Use to replace bare `print!`/`println!` calls.
    pub fn writer(&self) -> Writer<'_> {
        Writer { theme: self }
    }
}

/// `fmt::Write` / `io::Write` adapter that tints each payload.
pub struct Writer<'a> {
    theme: &'a Theme,
}

impl<'a> fmt::Write for Writer<'a> {
    fn write_str(&mut self, s: &str) -> fmt::Result {
        // Guard against stacking escapes inside a single write by only
        // colouring the whole payload once.
        let painted = self.theme.paint(s);
        io::stdout()
            .write_all(painted.as_bytes())
            .map_err(|_| fmt::Error)
    }
}

/// Paint and print a line of text to stdout in the default colour.
pub fn print_coloured(theme: &Theme, text: &str) {
    print!("{}", theme.paint(text));
}

//! Terminal UI utilities.
//!
//! Centralises how text is rendered to a terminal so the colour scheme can
//! be adjusted in one place — and later driven by a `/colour` REPL command
//! (the mechanism for switching the colour is in place now).
//!
//! The default foreground colour is **dark blue**. Colour codes are only
//! emitted when stdout is a terminal (TTY); when piped or redirected the
//! text stays plain so logs and captured output remain clean.
//!
//! To change the colour at runtime (future `/colour` command), mutate the
//! [`Theme::default_colour`] setting on the shared theme and re-render.

use std::fmt;
use std::io::{self, IsTerminal};
use std::sync::atomic::{AtomicU8, Ordering};

/// A foreground colour for terminal text.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Colour {
    DarkBlue,
    Reset,
    /// Plain output — no colour code emitted.
    Plain,
}

impl Colour {
    /// The ANSI SGR foreground escape sequence for this colour, or empty
    /// when the output is not a terminal.
    fn sgr(self, emit: bool) -> &'static str {
        if !emit {
            return "";
        }
        match self {
            Colour::DarkBlue => "\x1b[34m",
            Colour::Reset => "\x1b[0m",
            Colour::Plain => "",
        }
    }
}

/// Slot index for the default colour in the atomic scheme. Add more colours
/// here as `/colour` gains options.
const DEFAULT_COLOUR_SLOT: u8 = 0;

/// The active colour scheme.
///
/// A small process-wide atomic holds the current default colour so a future
/// `/colour` command can flip it without threading state through every
/// call site. Defaults to dark blue.
#[derive(Debug, Clone, Copy)]
pub struct Theme {
    /// Whether ANSI codes should be emitted (true when stdout is a TTY).
    emit: bool,
}

impl Default for Theme {
    fn default() -> Self {
        Self {
            emit: io::stdout().is_terminal(),
        }
    }
}

impl Theme {
    /// Create a theme for the current terminal.
    pub fn new() -> Self {
        Self::default()
    }

    /// Resolve the current default colour (dark blue unless changed).
    fn default_colour() -> Colour {
        match SCHEME.load(Ordering::Relaxed) {
            DEFAULT_COLOUR_SLOT => Colour::DarkBlue,
            _ => Colour::DarkBlue,
        }
    }

    /// Paint `s` in the current default colour (reset afterwards).
    fn paint(&self, s: &str) -> String {
        let fg = Self::default_colour().sgr(self.emit);
        let reset = Colour::Reset.sgr(self.emit);
        format!("{fg}{s}{reset}")
    }
}

/// Process-wide colour scheme (default dark blue).
static SCHEME: AtomicU8 = AtomicU8::new(DEFAULT_COLOUR_SLOT);

/// `fmt::Write` adapter that tints each formatted payload with the default
/// colour. Pass one to a `write!` call to colourise the whole string.
pub struct Writer<'a> {
    theme: &'a Theme,
}

impl<'a> fmt::Write for Writer<'a> {
    fn write_str(&mut self, s: &str) -> fmt::Result {
        let painted = self.theme.paint(s);
        io::stdout()
            .write_all(painted.as_bytes())
            .map_err(|_| fmt::Error)
    }
}

/// Paint and print `text` to stdout in the current default colour.
pub fn print_coloured(theme: &Theme, text: &str) {
    print!("{}", theme.paint(text));
}

//! Terminal UI utilities.
//!
//! Centralises how text is rendered to a terminal so the colour scheme can
//! be adjusted in one place — and later driven by a `/colour` REPL command
//! (the mechanism for switching the colour is in place now).
//!
//! The default foreground colour is **dark blue**. Colour codes are only
//! emitted when stdout is a terminal (TTY); when piped or redirected the
//! text stays plain so logs and captured output remain clean.
//!
//! Use [`print_coloured!`] / [`println_coloured!`] in place of `print!` /
//! `println!` to apply the current colour to a payload. To change the
//! colour at runtime (future `/colour` command), call [`set_default_colour`].

use std::io::{self, IsTerminal};
use std::sync::atomic::{AtomicU8, Ordering};

/// A foreground colour for terminal text.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Colour {
    DarkBlue,
    Reset,
    /// Plain output — no colour code emitted.
    Plain,
}

impl Colour {
    /// The ANSI SGR foreground escape sequence for this colour, or empty
    /// when the output is not a terminal.
    fn sgr(self, emit: bool) -> &'static str {
        if !emit {
            return "";
        }
        match self {
            Colour::DarkBlue => "\x1b[34m",
            Colour::Reset => "\x1b[0m",
            Colour::Plain => "",
        }
    }
}

/// Slot index for the default colour in the process-wide scheme. Add more
/// colours here as `/colour` gains options.
const DEFAULT_COLOUR_SLOT: u8 = 0;

/// Process-wide colour scheme (default dark blue). A small atomic keeps the
/// current default so a future `/colour` command can flip it without
/// threading state through every call site.
static SCHEME: AtomicU8 = AtomicU8::new(DEFAULT_COLOUR_SLOT);

/// Change the process-wide default colour (used by a future `/colour`
/// command and other runtime switches).
pub fn set_default_colour(colour: Colour) {
    let slot = match colour {
        Colour::DarkBlue => DEFAULT_COLOUR_SLOT,
        Colour::Reset | Colour::Plain => DEFAULT_COLOUR_SLOT,
    };
    SCHEME.store(slot, Ordering::Relaxed);
}

/// Resolve the process-wide default colour.
fn default_colour() -> Colour {
    match SCHEME.load(Ordering::Relaxed) {
        DEFAULT_COLOUR_SLOT => Colour::DarkBlue,
        _ => Colour::DarkBlue,
    }
}

/// Whether ANSI codes should be emitted (true when stdout is a TTY).
fn emit_colour() -> bool {
    io::stdout().is_terminal()
}

/// Apply the current default colour to `s`, wrapping in reset afterwards.
/// Returns `s` unchanged when not on a terminal.
pub fn tint(s: &str) -> String {
    if !emit_colour() {
        return s.to_string();
    }
    let fg = default_colour().sgr(true);
    let reset = Colour::Reset.sgr(true);
    format!("{fg}{s}{reset}")
}

/// Print a payload to stdout in the current default colour.
#[macro_export]
macro_rules! print_coloured {
    ($($arg:tt)*) => {
        ::std::print!("{}", $crate::ui::tint(&format!($($arg)*)))
    };
}

/// Print a payload plus newline to stdout in the current default colour.
#[macro_export]
macro_rules! println_coloured {
    () => {
        ::std::println!()
    };
    ($($arg:tt)*) => {
        ::std::println!("{}", $crate::ui::tint(&format!($($arg)*)))
    };
}

